log.raw:
{
  "critique": [
    {
      "design": "r1A",
      "good": "Complete keys make rows easy to identify, and the translations wrap without splitting words. The English column fits fully in the initial viewport.",
      "problems": "Several rows are tall, especially the invalid-email and shipping rows, while much of the key column remains empty vertically. The other language columns require substantial horizontal scrolling.",
      "cause": "The 227px key column preserves every identifier but consumes most of the viewport; the 90px Chinese and 120px Japanese columns make longer translations wrap over several lines."
    },
    {
      "design": "r1B",
      "good": "Complete keys and wider language columns produce the clearest, most compact rows of the three designs. Translation words remain intact, and no cell exceeds three lines.",
      "problems": "The initial viewport cuts through English text, so even the first translation cannot always be read without scrolling. Reaching Arabic takes the most horizontal travel.",
      "cause": "The 227px key and 150px English columns together exceed the viewport, while the five generous widths produce a 738px table."
    },
    {
      "design": "r1C",
      "good": "The initial viewport shows complete English and Chinese columns and the start of Japanese, giving a better immediate sense of the multilingual structure. It also requires less horizontal travel.",
      "problems": "Keys break across lines, sometimes leaving a single letter on its own. Narrow translation columns create dense vertical stacks and very tall rows, making comparison across the row harder.",
      "cause": "The 160px key width cannot hold the longer identifiers; 65px for Chinese and 80px for Japanese leave only 44px and 59px of text space, respectively."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-anchor",
      "widths": [227, 132, 105, 140, 120],
      "change": "Keep complete keys and the fully visible English column from r1A, while giving Chinese and Japanese more space to reduce tall rows. This tests a compromise between initial readability and scrolling."
    },
    {
      "name": "compact-comparison",
      "widths": [190, 120, 90, 120, 110],
      "change": "Trade some key wrapping for a shorter scroll than the intact-key designs, while retaining substantially more translation space than r1C. The first viewport should show English and part of Chinese."
    },
    {
      "name": "viewport-first",
      "widths": [100, 80, 55, 65, 59],
      "change": "Test the unexplored no-scroll alternative at 359px. It exposes all languages together but accepts broken identifiers and heavy wrapping; the render will show whether maintaining the full row in view compensates for that cost."
    }
  ]
}
